draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';

  // seed
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 10, 0, 2 * Math.PI);
  ctx.fill();

  // sprout
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 10);
  ctx.lineTo(W/2, H/2 + 10 + 50 * Math.sin(t));
  ctx.stroke();

  // leaves
  ctx.fillStyle = 'green';
  ctx.beginPath();
  ctx.arc(W/2 - 20 * Math.sin(t), H/2 + 60 + 50 * Math.sin(t), 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2 + 20 * Math.sin(t), H/2 + 60 + 50 * Math.sin(t), 10, 0, 2 * Math.PI);
  ctx.fill();

  // nutrients
  ctx.fillStyle = 'blue';
  ctx.beginPath();
  ctx.arc(W/2 - 30 * Math.cos(t), H/2 - 20 * Math.sin(t), 5, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2 + 30 * Math.cos(t), H/2 - 20 * Math.sin(t), 5, 0, 2 * Math.PI);
  ctx.fill();

  ctx.restore();
}
